COMMENT ON COLUMN public."user_tenant"."role" IS 'RAGFlow v0.26.4 `user_tenant` 记录中的“role”字段；精确枚举/JSON 子结构由该版本业务模型约束。 PostgreSQL 类型：character varying(32)；不可为空。';
COMMENT ON COLUMN public."user_tenant"."invited_by" IS 'RAGFlow v0.26.4 `user_tenant` 记录中的“invited by”字段；精确枚举/JSON 子结构由该版本业务模型约束。 PostgreSQL 类型：character varying(32)；不可为空。';
COMMENT ON COLUMN public."user_tenant"."status" IS '当前业务状态；允许值由表上的 CHECK 约束或上游枚举控制。 PostgreSQL 类型：character varying(1)；允许为空，表示未提供或尚未产生。';
DO $$ DECLARE item record; BEGIN
    FOR item IN SELECT c.relname, pg_get_indexdef(c.oid) AS definition FROM pg_class c
      JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind='i'
    LOOP EXECUTE format('COMMENT ON INDEX %I.%I IS %L','public',item.relname,
      '索引：支持其键列检索；唯一索引同时限制重复。实际定义：'||item.definition); END LOOP;
    FOR item IN SELECT c.conname, t.relname, pg_get_constraintdef(c.oid) AS definition
      FROM pg_constraint c JOIN pg_class t ON t.oid=c.conrelid
      JOIN pg_namespace n ON n.oid=t.relnamespace WHERE n.nspname='public'
    LOOP EXECUTE format('COMMENT ON CONSTRAINT %I ON %I.%I IS %L',item.conname,'public',item.relname,
      '数据完整性约束：'||item.definition); END LOOP;
    FOR item IN SELECT t.tgname, c.relname, pg_get_triggerdef(t.oid) AS definition
      FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace
      WHERE n.nspname='public' AND NOT t.tgisinternal
    LOOP EXECUTE format('COMMENT ON TRIGGER %I ON %I.%I IS %L',item.tgname,'public',item.relname,
      '写入时维护记录的更新时间。实际定义：'||item.definition); END LOOP;
END $$;
COMMENT ON SCHEMA public IS 'RAG 专用数据库内的业务结构；归属 lazytt_rag，由对应版本迁移维护。';
COMMENT ON SEQUENCE public.tenant_llm_id_seq IS '为对应记录生成递增整数标识，由数据库默认值消费。';
COMMIT;
